SELECT
  e.id,
  e."fleetId" AS fleet_id,
  e.type AS db_type,
  s.type AS new_type,
  e.make AS db_make,
  s.make AS new_make,
  e.model AS db_model,
  s.model AS new_model,
  e."registrationNumber" AS db_registration,
  s."registrationNumber" AS new_registration,
  e."vinSerialId" AS db_vin,
  s."vinSerialId" AS new_vin,
  e."fuelConsumption" AS db_fuel_consumption,
  s."fuelConsumption" AS new_fuel_consumption,
  e.location::text AS db_location,
  s.location AS new_location,
  e."companyId" AS db_company_id,
  s.company_name AS new_company_name,
  e.status::text AS db_status,
  s.status AS new_status
FROM "Equipment" e
JOIN tmp_equipment_update s ON s.id = e.id
WHERE
  (e.type::text IS DISTINCT FROM s.type
  OR e.make IS DISTINCT FROM s.make
  OR e.model IS DISTINCT FROM s.model
  OR e."registrationNumber" IS DISTINCT FROM s."registrationNumber"
  OR e."vinSerialId" IS DISTINCT FROM s."vinSerialId"
  OR e."engineCapacity" IS DISTINCT FROM s."engineCapacity"
  OR e."fuelConsumption" IS DISTINCT FROM s."fuelConsumption"
  OR e."fuelConsumptionUnit"::text IS DISTINCT FROM s."fuelConsumptionUnit"
  OR e."loadingCarryingCapacityTonnes" IS DISTINCT FROM s."loadingCarryingCapacityTonnes"
  OR e.location::text IS DISTINCT FROM s.location
  OR e."locationOtherText" IS DISTINCT FROM s."locationOtherText"
  OR e.status::text IS DISTINCT FROM s.status
  OR e."companyId" IS DISTINCT FROM (
      SELECT ec.id
      FROM "EquipmentCompany" ec
      WHERE LOWER(TRIM(ec.name)) = LOWER(TRIM(s.company_name))
      ORDER BY CASE WHEN ec."siteId" IS NOT DISTINCT FROM e."siteId" THEN 0 ELSE 1 END
      LIMIT 1
    ))
ORDER BY e."fleetId";

